def comps_grid(X, exclude={1}):
 Hh,Ww=X.shape; ids=np.full(X.shape,-1,int); comps=[]
 for r in range(Hh):
  for c in range(Ww):
   v=int(X[r,c])
   if v in exclude or ids[r,c]>=0:continue
   ix=len(comps); pts=[]; q=[(r,c)];ids[r,c]=ix
   while q:
    y,x=q.pop();pts.append((y,x))
    for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
     if 0<=yy<Hh and 0<=xx<Ww and ids[yy,xx]<0 and X[yy,xx]==v:
      ids[yy,xx]=ix;q.append((yy,xx))
   comps.append((v,pts))
 return ids,comps
